import React, { useRef, useState, useEffect } from "react";
import Image from "next/image";

export default function ConceptBoard({ images }) {
  const canvasRef = useRef(null);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [scale, setScale] = useState(1);
  const [isDragging, setIsDragging] = useState(false);
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });
  const [imagePositions, setImagePositions] = useState({});
  const [activeImage, setActiveImage] = useState(null);

  // Center canvas on mount
  useEffect(() => {
    setOffset({ x: 0, y: 0 });
    setScale(1);
  }, []);

  const handleWheel = (e) => {
    e.preventDefault();
    const delta = -e.deltaY / 500;
    setScale((prev) => Math.min(Math.max(prev + delta, 0.1), 3));
  };

  const handleMouseDown = (e) => {
    setIsDragging(true);
    setLastMousePos({ x: e.clientX, y: e.clientY });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    setActiveImage(null);
  };

  const handleMouseMove = (e) => {
    if (activeImage) {
      setImagePositions((prev) => ({
        ...prev,
        [activeImage]: {
          x: prev[activeImage].x + (e.clientX - lastMousePos.x) / scale,
          y: prev[activeImage].y + (e.clientY - lastMousePos.y) / scale,
        },
      }));
    } else if (isDragging) {
      setOffset((prev) => ({
        x: prev.x + (e.clientX - lastMousePos.x),
        y: prev.y + (e.clientY - lastMousePos.y),
      }));
    }
    setLastMousePos({ x: e.clientX, y: e.clientY });
  };

  const handleImageMouseDown = (e, id) => {
    e.stopPropagation();
    setActiveImage(id);
    setLastMousePos({ x: e.clientX, y: e.clientY });
  };

  const getInitialImagePos = (id, index) => {
    if (!imagePositions[id]) {
      const pos = { x: index * 250, y: 0 };
      setImagePositions((prev) => ({ ...prev, [id]: pos }));
      return pos;
    }
    return imagePositions[id];
  };

  return (
    <div
      className="relative w-full h-[calc(100vh-200px)] overflow-hidden bg-neutral-900"
      onWheel={handleWheel}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      onMouseMove={handleMouseMove}
    >
      <div
        ref={canvasRef}
        className="absolute left-1/2 top-1/2"
        style={{
          transform: `translate(-50%, -50%) translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
          transformOrigin: "center center",
        }}
      >
        {images.map((img, i) => {
          const pos = getInitialImagePos(img.id, i);
          return (
            <div
              key={img.id}
              onMouseDown={(e) => handleImageMouseDown(e, img.id)}
              className="absolute cursor-move rounded-lg shadow-lg"
              style={{
                left: `${pos.x}px`,
                top: `${pos.y}px`,
              }}
            >
              <Image
                src={img.url}
                alt={img.name}
                width={200}
                height={200}
                className="rounded-lg border border-white"
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}
